package com.lyra.studio; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; import android.webkit.WebView; import android.webkit.WebViewClient; import android.webkit.WebChromeClient; import android.view.WindowManager; import android.app.Activity; @DesignerComponent(version = 1, description = "WebViewer customizado que se adapta ao teclado virtual para não cobrir o conteúdo.", category = ComponentCategory.EXTENSION, nonVisible = false, iconName = "images/web.png") @SimpleObject(external = true) public class KeyboardSafeWebViewer extends AndroidViewComponent { private WebView webview; private Activity activity; public KeyboardSafeWebViewer(ComponentContainer container) { super(container); this.activity = container.$context(); /* Configura a janela para redimensionar quando o teclado aparecer, evitando sobreposicao */ this.activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); /* Inicializa o WebView com recursos avancados simplificados */ this.webview = new WebView(activity); this.webview.getSettings().setJavaScriptEnabled(true); this.webview.getSettings().setDomStorageEnabled(true); this.webview.setWebViewClient(new WebViewClient()); this.webview.setWebChromeClient(new WebChromeClient()); /* Adiciona a view ao container do App Inventor */ container.$add(this); } @Override public android.view.View getView() { return webview; } @SimpleFunction(description = "Carrega uma URL no WebViewer.") public void GoToUrl(String url) { webview.loadUrl(url); } @SimpleFunction(description = "Recarrega a página atual.") public void Reload() { webview.reload(); } @SimpleFunction(description = "Volta para a página anterior, se possível.") public void GoBack() { if (webview.canGoBack()) { webview.goBack(); } } @SimpleFunction(description = "Avança para a próxima página, se possível.") public void GoForward() { if (webview.canGoForward()) { webview.goForward(); } } @SimpleProperty(description = "Retorna a URL atual.") public String CurrentUrl() { return webview.getUrl(); } }